using var client = new PromptLayerClient(apiKey);

var request = global::System.Text.Json.JsonSerializer.Deserialize<global::PromptLayer.AddReportColumnRequest>(
    @"{
  ""report_id"": 456,
  ""column_type"": ""PROMPT_TEMPLATE"",
  ""name"": ""Generate Answer"",
  ""configuration"": {
    ""template"": {
      ""name"": ""qa_template"",
      ""version_number"": null
    },
    ""prompt_template_variable_mappings"": {
      ""question"": ""input_question""
    },
    ""engine"": {
      ""provider"": ""openai"",
      ""model"": ""gpt-4"",
      ""parameters"": {
        ""temperature"": 0.7
      }
    }
  }
}")!;

var response = await client.Reports.AddReportColumnAsync(
    request: request
);

